  if hit and v['age']<60:
   reason=('no_progress_below_entry_and_ma20' if weak else 'profit_armed_close_drawdown10') if rule=='H20_P15' else rule
   pending=reason;trigger={'trigger_t':v['t'],'trigger_date':v['date'],'trigger_age':v['age'],'trigger_gain_pct':v['gain_pct'],'trigger_peak_close_gain_pct':v['peak_close_gain_pct'],'trigger_drawdown_close_pct':v['drawdown_close_pct'],'trigger_ma20':v['ma20']}
